import { workedAnswers, sources } from './course.mjs';
import { courseEvidence } from './investigation.mjs';
import { aggregate } from './analytics.mjs';
import { esc, num, usd, pct, bars, scatter, metricsTable } from './charts.mjs';

export const evidenceTable=(caption,headers,rows)=>`<div class="table-scroll"><table><caption>${caption}</caption><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'}${i?'':' scope="row"'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const inspectButton=(row,label='查看原始行')=>`<button class="button compact source-row-link" data-action="inspect-row" data-sheet="${esc(row.sourceSheet)}" data-row="${row.sourceRow}">${label} · ${esc(row.sourceSheet)}!${row.sourceRow} ↗</button>`;
const step=(n,title,body)=>`<section class="panel solution-step"><div class="solution-step-title"><span>${n}</span><h3>${title}</h3></div>${body}</section>`;
const formula=(label,expression,value)=>`<div class="formula-card"><strong>${label}</strong><code>${expression}</code><b>${value}</b></div>`;

export function shareChart(channels) {
 return `<div class="share-chart" role="img" aria-label="渠道花费份额与收入份额对比，范围零至百分之百"><div class="share-legend"><span><i></i>花费份额</span><span><i></i>收入份额</span><span>共同尺度：0–100%</span></div>${channels.map(g=>`<div class="share-group"><strong>${esc(g.name)}</strong>${[['花费',g.costShare],['收入',g.revenueShare]].map(([l,v],i)=>`<div class="share-row"><span>${l}</span><div class="share-track"><i class="${i?'revenue':''}" style="width:${Math.max(0,v||0)*100}%"></i></div><b>${pct(v)}</b></div>`).join('')}</div>`).join('')}</div><p class="chart-caption">DoubleClick 全量。花费份额 = 渠道花费 / 全部花费；收入份额 = 渠道收入 / 全部收入。两种份额各自合计 100%，不是两类金额直接相除。</p>`;
}

export function storyEvidence(data,localAvailable) {
 const e=courseEvidence(data);
 if(!e)return `<section class="panel"><h2>用原表看清业务处境</h2><p>读取已经准备的工作簿后，展示渠道投入与产出分化、零预订投入和需要回答的经营问题。</p><button class="button primary" data-action="${localAvailable?'load-local':'load-mirror'}">${localAvailable?'载入本地案例数据':'载入公开镜像'} →</button><a class="button quiet" href="#data">查看数据来源与导入</a></section>`;
 const {total:t,leader:l,best:b,zeroTotal:z}=e;
 return `<section class="panel dilemma-section"><div class="eyebrow">当前处境 / 从工作簿复算</div><h2>整体有销售回报，投放取舍仍然不清楚</h2><p>主表记录了 ${usd(t.cost,2)} 广告花费、${num(t.bookings)} 次预订和 ${usd(t.revenue,2)} 销售收入，整体 ROAS 为 ${num(t.roas,2)} 倍。这个平均数还没有告诉团队，下一步应扩大哪个渠道、调整哪些活动。</p><div class="dilemma-cards"><article><span>01 / 规模与效率分离</span><h3>${esc(l.name)}</h3><strong>${pct(l.costShare)}</strong><p>占主表花费，对应 ${pct(l.revenueShare)} 收入。需要进一步解释活动结构。</p></article><article><span>02 / 高回报能否扩量</span><h3>${esc(b?.name||'无可计算渠道')}</h3><strong>${num(b?.roas,2)}× ROAS</strong><p>历史回报领先，花费占比 ${pct(b?.costShare)}。新增流量能否保持效率仍待验证。</p></article><article><span>03 / 投入落在哪里</span><h3>零预订记录</h3><strong>${usd(z.cost,2)}</strong><p>${num(z.count)} 条记录，对应 ${pct(z.cost/t.cost)} 花费。应逐项诊断，不能全部当成可省预算。</p></article></div><h3>渠道投入与产出分布</h3>${shareChart(e.channels)}<div class="decision-question"><strong>团队真正要回答：</strong>用什么衡量成功？渠道怎么分工？活动和关键词改什么？Kayak 应扮演什么角色？</div><p class="small">以上为当前导入文件的历史观察，不是官方标准答案。主表缺少日期，无法判断增长、衰退或预算超支；${esc(data.meta.period)}</p><a class="button" href="#data">先看看这些数字来自哪些原始记录 →</a></section>`;
}

function channelAction(g,e) {
 if(g.cpa===null||g.roas===null)return ['先核对数据','效率分母不足，暂不据此配置预算。'];
 if(g.name===e.leader.name&&g.roas<e.total.roas)return ['保留规模，优先优化','先检查主要活动与关键词；不因渠道均值较低而整渠道关停。'];
 if(g.roas>=e.total.roas&&g.cpa<=e.total.cpa)return ['保护表现，验证扩量','先核对关键词结构与新增流量，再分步验证，不能按历史 ROAS 无限追加。'];
 if(g.cpa>e.total.cpa&&g.roas<e.total.roas)return ['优先诊断低效投入','下钻活动、意图与出价；用 CPA、预订量和收入共同复查。'];
 return ['维持并细分观察','结合每次预订收入和活动组合，避免仅凭低 CVR 或单一象限做取舍。'];
}
function solution1(data,e){
 const t=e.total;
 const metricRows=[['CPC','Total Cost ÷ Clicks',`${usd(t.cost,2)} ÷ ${num(t.clicks)}`,usd(t.cpc,4)],['CTR','Clicks ÷ Impressions',`${num(t.clicks)} ÷ ${num(t.impressions)}`,pct(t.ctr)],['CVR','Bookings ÷ Clicks',`${num(t.bookings)} ÷ ${num(t.clicks)}`,pct(t.cvr)],['CPA','Total Cost ÷ Bookings',`${usd(t.cost,2)} ÷ ${num(t.bookings)}`,usd(t.cpa,4)],['ROAS','Amount ÷ Total Cost',`${usd(t.revenue,2)} ÷ ${usd(t.cost,2)}`,num(t.roas,4)+'×'],['每次预订收入','Amount ÷ Bookings',`${usd(t.revenue,2)} ÷ ${num(t.bookings)}`,usd(t.revenuePerBooking,4)],['广告费后余额','Amount − Total Cost',`${usd(t.revenue,2)} − ${usd(t.cost,2)}`,usd(t.balance,2)]];
 return step(1,'先确认经营底表的范围',`<p>选取 ${esc(data.meta.primarySheet)} 的 ${num(data.rows.length)} 条可计算明细，按 Total Cost、Clicks、预订和 Amount 汇总；Kayak 保持独立。原始比率列只用于核对，不能再直接求平均。</p><div class="calculation-flow">${[['曝光',num(t.impressions)],['点击',num(t.clicks)],['预订',num(t.bookings)],['销售收入',usd(t.revenue,2)]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><p class="chart-caption">流程表示业务关系，框宽不编码数量。计数不是去重用户漏斗；点击率与预订率的分母不同。</p><a class="button compact" href="#data">查看全表与原始字段 →</a>`)
 +step(2,'把分子、分母和结果一起核对',`${evidenceTable('主表整体指标；内部按原精度计算，展示值四舍五入',['指标','原始字段 / 公式','代入总量','结果'],metricRows)}<div class="notice info"><p>有点击记录的逐行 CPC 简单平均为 ${usd(e.simpleCpc,4)}，整体 CPC 为 ${usd(t.cpc,4)}。前者把不同点击规模的关键词等权处理；经营底表使用后者。</p></div>`)
 +step(3,'回到异常记录，而非直接删掉',`${evidenceTable('零点击或预订高于点击的全部记录，保留在整体汇总中',['原始位置','关键词','点击','预订','处理意见'],e.anomalies.map(r=>[inspectButton(r),esc(r.keyword),num(r.clicks),num(r.bookings),'保留并核对计数 / 归因；当前文件不能确认原因']))}<p>另有 ${num(e.zeroTotal.count)} 条零预订记录，花费 ${usd(e.zeroTotal.cost,2)}。若把它们全部删除，剩余行计算的 ROAS 将变成 ${num(e.activeTotal.roas,2)} 倍，掩盖已经发生的投入。这是筛选偏差，不是优化结果。</p>`)
 +step(4,'解释指标如何联动，并选定经营评价组合',`<div class="formula-grid">${formula('获客成本链','CPA = CPC ÷ CVR',usd(t.cpa,2))}${formula('广告销售回报链','ROAS = CVR × 每次预订收入 ÷ CPC',num(t.roas,2)+'×')}</div><p>当其他条件不变，CPC 上升会推高 CPA、压低 ROAS；CVR 提升则方向相反。CTR 影响曝光到点击环节，不能单独保证预订或收入改善。</p>${evidenceTable('建议采用的 KPI 组合（本课参考判断）',['角色','指标','用来回答什么'],[['业务结果','预订量、销售收入','销售规模是否达到经营目标？'],['经营约束','CPA、ROAS','拿到这些预订付出多大广告成本？'],['诊断指标','CPC、CTR、CVR、每次预订收入','差异发生在点击成本、转化还是订单收入？']])}`);
}
function solution2(data,e){
 const l=e.leader,b=e.best;
 return step(1,'统一口径后，按原渠道名称汇总',`<p>用第一题相同公式，按 Publisher Name 分组。参考线取整体 CPC ${usd(e.total.cpc,2)}、CVR ${pct(e.total.cvr)}；US、Global、Overture 都保留原始标签。</p>${metricsTable(e.channels,{caption:'逐渠道经营底表 · DoubleClick 全量'})}`)
 +step(2,'用份额差异定位需要解释的渠道',`${shareChart(e.channels)}<p>${esc(l.name)} 占 ${pct(l.costShare)} 花费、${pct(l.revenueShare)} 收入；${esc(b?.name)} 占 ${pct(b?.costShare)} 花费、${pct(b?.revenueShare)} 收入。份额差异提示效率差异，但还需结合样本规模与关键词组合解释。</p>`)
 +step(3,'把差异拆回点击成本与预订率',`${scatter(e.channels,e.total)}<p>同一象限内也不必采取相同动作。例如销售收入取决于预订量和每次预订收入，低 CVR 渠道可能仍有可接受的 CPA；必须回看底表。</p>`)
 +step(4,'明确给出逐渠道策略',`${evidenceTable('参考建议；相对整体指标的描述性比较，不是最优预算解',['渠道','象限 / 证据','建议','执行与验证'],e.channels.map(g=>{const a=channelAction(g,e);return [esc(g.name),`${g.quadrant}<br>CPA ${usd(g.cpa,2)} · ROAS ${num(g.roas,2)}×`,a[0],a[1]]}))}<p><strong>本题回答：</strong>${workedAnswers.q2.conclusion} 下一题优先检查 ${esc(l.name)}，因为它当前花费最高；这是诊断优先级，不等于判断整个平台无效。</p>`);
}
function solution3(data,e){
 const top=e.campaigns.slice(0,3),contrast=e.campaignContrast;
 return step(1,'从主要渠道进入活动，而非直接对渠道贴标签',`<div class="trace-path"><span>全量主表</span><b>→</b><span>${esc(e.leader.name)}</span><b>→</b><span>${e.campaigns.length} 个活动</span><b>→</b><span>按花费取前 3 个</span></div><p>该渠道投入 ${usd(e.leader.cost,2)}，历史 ROAS ${num(e.leader.roas,2)} 倍。活动对比限定在同一渠道，避免同名 Campaign 被跨渠道误合并。</p>${metricsTable(top,{caption:'当前花费最高渠道的前三个高花费活动',showPublisher:true})}`)
 +step(2,'同时看活动体量与回报，定位主要分化',`<div class="two-columns"><div><h4>广告花费（USD）</h4>${bars(top,{title:'活动花费',limit:3})}</div><div><h4>广告销售回报（倍）</h4>${bars(top,{key:'roas',format:v=>num(v,2)+'×',title:'ROAS',limit:3})}</div></div><p>两图分别使用各自的货币与倍数尺度，均从零起。高投入配合低回报的活动应优先下钻，不能仅因花费高就削减有效活动。</p>${contrast.strong&&contrast.weak?`<div class="notice info"><p>这三项活动中，${esc(contrast.strong.name)} 记录 ${num(contrast.strong.bookings)} 次预订、ROAS ${num(contrast.strong.roas,2)} 倍；${esc(contrast.weak.name)} 花费 ${usd(contrast.weak.cost,2)}、${num(contrast.weak.bookings)} 次预订、ROAS ${num(contrast.weak.roas,2)} 倍。前者支持保护有效覆盖，后者应优先核对流量与状态。活动均值不直接证明品牌、文案或策略的因果效果。</p></div>`:''}`)
 +step(3,'把结论落到真实关键词、状态与源行',`${evidenceTable('当前最高花费渠道的匹配方式 / 出价策略组合；未提供表示原字段缺失',['Match Type / Bid Strategy','花费','点击','预订','CPA','ROAS'],e.strategies.map(g=>[esc(g.name),usd(g.cost,2),num(g.clicks),num(g.bookings),usd(g.cpa,2),num(g.roas,2)+'×']))}<p>策略组合与关键词意图、活动、状态可能同时变化。先把此表作为检查线索，再逐行决定动作；不能直接断言某匹配方式导致更好效果。</p><p>以下样例在 ${esc(e.leader.name)} 中选取：有预订且收入高于花费的记录按预订量取第一；有预订、Live 且收入低于花费的记录按花费取第一；零预订记录按花费取第一。不是统计显著性规则。</p><div class="action-examples">${e.actions.map(({kind,row:r,metrics:m})=>{const title=kind==='protect'?'保护有效投放':kind==='review'?'优先核查在投低效词':'复盘零预订投入';const action=kind==='protect'?'保留有效覆盖，监测扩大覆盖后的 CPA 与预订变化；不能由品牌或匹配标签推断因果。':kind==='review'?'核对搜索意图、匹配与出价，提出对照调整；获取广告文案和落地页材料后再判断问题来源。':r.status==='Paused'?'原表已经 Paused：先复核暂停时间和转化归因；只有新的流量与效果证据支持时，再考虑重启。':'先核对当前状态、归因和流量意图，再决定调整或保留观察；零预订不等于永久无价值。';return `<article class="panel action-example"><div class="eyebrow">${title} / 参考行动</div><h4>${esc(r.keyword)}</h4><p>${esc(r.publisher)} → ${esc(r.campaign)}</p><div class="tags"><span class="tag">${esc(r.status)}</span><span class="tag">${esc(r.matchType)}</span><span class="tag">${esc(r.bidStrategy)}</span></div><p><strong>${num(r.clicks)}</strong> 次点击 · <strong>${num(r.bookings)}</strong> 次预订 · 花费 <strong>${usd(r.cost,2)}</strong> · ROAS <strong>${num(m.roas,2)}×</strong></p><p>${action}</p>${inspectButton(r)}</article>`}).join('')||'<p>当前文件不足以按这些规则选出样例；请从交互工作台自行核查，不填造示例。</p>'}</div>`)
 +step(4,'把动作、验证指标和证据缺口连起来',`${evidenceTable('从行动到验证；下列为后续建议，未声称已经执行',['行动','观察指标','还需要什么'],[['保护有效覆盖','预订量、CPA、ROAS','流量容量、竞争与新增流量结构'],['核查并调整低效词','CPC、CVR、CPA','搜索词日志、出价变更和归因口径'],['复盘零预订 / 已暂停词','点击与预订回传、状态','暂停时间、转化延迟、是否存在遗漏'],['验证文案或落地页','同口径下的转化与收入','实际素材、页面版本和对照实验']])}<p>新增关键词只能作为待测方向；工作簿没有这些词的历史表现，不能为它们补造结果。</p>`);
}
function solution4(data,e){
 const k=e.kayak;
 if(!k)return `<section class="panel"><h3>缺少 Kayak，数值答案不能生成</h3><p>当前文件没有可识别的 Kayak 汇总。方法和建议边界可阅读，数值比较需要完整工作簿。</p><a class="button" href="#data">查看并导入完整数据 →</a></section>`;
 return step(1,'只用 Kayak 自身的分子和分母计算',`<p>原表期间：${esc(data.meta.kayakPeriod)}。${inspectButton(data.kayak)}</p><div class="formula-grid">${formula('CPC',`${usd(k.cost,2)} ÷ ${num(k.clicks)}`,usd(k.cpc,2))}${formula('CVR',`${num(k.bookings)} ÷ ${num(k.clicks)}`,pct(k.cvr))}${formula('CPA',`${usd(k.cost,2)} ÷ ${num(k.bookings)}`,usd(k.cpa,2))}${formula('ROAS',`${usd(k.revenue,2)} ÷ ${usd(k.cost,2)}`,num(k.roas,2)+'×')}</div>${metricsTable([{name:'Kayak · 独立期间',...k}],{caption:'Kayak 独立核算；无曝光数据时 CTR 不可计算'})}`)
 +step(2,'并列效率，同时保留不可比条件',`<div class="notice"><p>主表没有日期。以下是不同观察范围的描述性参照，不是同期渠道效果测试，也不合并总量。</p></div>${bars([...e.channels,{name:'Kayak（独立单周）',...k}],{key:'roas',title:'历史 ROAS（不同观察范围）',format:v=>num(v,2)+'×'})}${evidenceTable('哪些已知、哪些尚不能回答',['维度','DoubleClick','Kayak','影响'],[['期间',esc(data.meta.period),esc(data.meta.kayakPeriod),'不能确认同期，不能直接外推'],['样本',`${num(e.total.clicks)} 点击 / ${num(e.total.bookings)} 预订`,`${num(k.clicks)} 点击 / ${num(k.bookings)} 预订`,'规模不同，要验证可获得流量'],['粒度','关键词投放记录','渠道汇总','Kayak 无法做同样的关键词诊断'],['曝光 / CTR',`${num(e.total.impressions)} / ${pct(e.total.ctr)}`,'未提供','不能比较点击率'],['归因 / 扩量','无完整归因和增量证据','无扩量曲线','不能求得真实最优预算']])}`)
 +step(3,'把前三题连成一份明确的建议',`<div class="decision-memo"><div class="eyebrow">给 Media Contacts 的参考备忘录</div><h3>先优化现有组合，再验证 Kayak 的增量机会</h3><p><strong>目标：</strong>沿用第一题的预订量、销售收入、CPA 和 ROAS；主表当前基线为 CPA ${usd(e.total.cpa,2)}、ROAS ${num(e.total.roas,2)} 倍。</p><p><strong>现有渠道：</strong>按第二题差异化策略分工，保护 ${esc(e.best?.name||'表现较好的渠道')} 的有效覆盖，核对扩量能力；优先检查花费最高的 ${esc(e.leader.name)} 的活动结构。</p><p><strong>执行对象：</strong>采用第三题的活动下钻与关键词源行行动，结合 Status 决定维持、核查或调整，不直接删除全部零预订记录。</p><p><strong>Kayak：</strong>历史 CPA ${usd(k.cpa,2)}、ROAS ${num(k.roas,2)} 倍，支持把它列为进一步验证的候选；在期间、归因和流量规模未核对前，不把全部预算迁入。</p></div>`)
 +step(4,'给出可执行的验证顺序',`${evidenceTable('建议的下一轮工作；条件由分析团队提出，不是案例已执行事实',['次序','做什么','什么证据决定下一步'],[['先对齐','取得渠道同期报表，确认成本、归因、转化回传与收入口径','期间一致、异常记录解释充分，才做下一步比较'],['再优化','执行第三题中的具体核查与有对照的投放调整','同时观察预订规模与 CPA、ROAS，不只看 CTR'],['再验证 Kayak','收集可获取流量、扩量报价、同期收入与预订','确认边际成本和转化表现，再决定是否扩大'],['最后复盘','对照既定 KPI 总结保留、扩大、调整与停止项','若要主张额外订单来自广告，需有效对照证据']])}<p><strong>最终回答：</strong>${workedAnswers.q4.conclusion} 当前数据支持一个有条件的验证与优化方案，不支持精确的最优预算金额。</p>`);
}

export function workedSolution(id,data) {
 const a=workedAnswers[id],e=courseEvidence(data);
 return `<div class="worked-solution" data-solution="${id}"><section class="answer-summary"><div class="eyebrow">参考答案 / 与问题同时开放</div><h2>本题的回答</h2><p>${a.conclusion}</p><div class="method-strip">${a.steps.map((s,i)=>`<div><b>${i+1}</b><span>${s}</span></div>`).join('')}</div><p class="small">本课依据当前文件形成的可复算参考解答，非 Kellogg 官方标准答案。建议允许有证据支持的不同选择。</p></section>${e?({q1:solution1,q2:solution2,q3:solution3,q4:solution4}[id])(data,e):`<section class="panel"><h3>解题方法</h3><p>${a.method}</p><p>读取数据后，将在这里显示逐步代入的数值、图表和源行。不会用示例数值替代。</p><a class="button primary" href="#data">读取案例数据 →</a></section>`}<div class="notice info"><p><strong>结论边界：</strong>${a.boundary}</p></div></div>`;
}
